<section class="fuel-panel ua-history" aria-labelledby="activity-history-title">
    <div class="fuel-panel-head"><div><h2 id="activity-history-title">Activity history</h2><p>Latest events first · {{ config('app.timezone') }}</p></div><button type="button" class="fuel-button fuel-button-small" id="activity-refresh"><i class="bi bi-arrow-clockwise" aria-hidden="true"></i> Refresh</button></div>
    <div class="ua-toolbar"><label class="ua-search" for="activity-search"><i class="bi bi-search" aria-hidden="true"></i><input id="activity-search" name="search" type="search" form="activity-filters" value="{{ $filters['search'] ?? '' }}" placeholder="Search user, module, or record ID" maxlength="100"></label><span id="activity-updated"></span></div>
    <div class="ua-table-wrap"><table class="table" id="activity-history-table"><thead><tr><th>When</th><th>User</th><th>Module</th><th>Action</th><th>Record</th><th>Details</th></tr></thead><tbody id="activity-history-rows"><tr><td colspan="6" class="ua-empty">Loading activity…</td></tr></tbody></table></div>
    <div class="ua-pagination"><span id="activity-page-info" role="status" aria-live="polite"></span><div><button type="button" class="fuel-button fuel-button-small" id="activity-previous" disabled><i class="bi bi-chevron-left" aria-hidden="true"></i> Previous</button><button type="button" class="fuel-button fuel-button-small" id="activity-next" disabled>Next <i class="bi bi-chevron-right" aria-hidden="true"></i></button></div></div>
    <p class="ua-footnote"><i class="bi bi-shield-check" aria-hidden="true"></i> Read-only history for SUAdmin. Page views and submitted requests are separate from confirmed record changes.</p>
</section>
